-- PT104-S1-Q13. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT104-S1-Q13$batch04$ AND q.stimulus=$batch04$Problems caused by the leaching of pollutants from dumps and landfills are worst in countries with an annual per capita economic output of $4,000 to $5,000, and less severe for considerably poorer and considerably richer countries. This is so because pollution problems increase during the early stages of a country’s industrial development but then diminish as increasing industrial development generates adequate resources to tackle such problems. Therefore, problems caused by such leaching in Country X, where the annual per capita economic output is now $5,000, should begin to diminish in the next few years.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the argument depends?$batch04$ AND q.correct_choice=$batch04$C$batch04$) THEN RAISE EXCEPTION 'Question changed: PT104-S1-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT104-S1-Q13$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S1-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT104-S1-Q13$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Leaching problems in Country X should begin to diminish in the next few years.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Leaching problems are worst at $4,000 to $5,000 per capita output, because pollution rises early in industrial development and falls once further development brings the resources to deal with it. Country X is now at $5,000.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The problems fall as *increasing* industrial development generates resources. The argument predicts a decline, so it is counting on Country X to keep developing. If development stalls, nothing produces the resources.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Country X's industrial development will keep increasing.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT104-S1-Q13$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Fines might help, but the argument relies on development bringing resources, not on any specific policy.$batch04$), ($batch04$B$batch04$, $batch04$Pollution from neighboring countries does not affect leaching from Country X's dumps.$batch04$), ($batch04$C$batch04$, $batch04$Negate it: industrial development in Country X will *not* increase. Then the resources to tackle pollution never arrive, and there is no reason to expect the problems to diminish.$batch04$), ($batch04$D$batch04$, $batch04$Country X is already at the income level where the problems peak, so it has already begun industrializing. The author does not assume it has yet to start.$batch04$), ($batch04$E$batch04$, $batch04$How Country X compares with other countries does not affect what will happen to it.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT104-S1-Q13$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
